const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduced){document.body.classList.add('motion');const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>o.observe(e));}
document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-product]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const im=document.querySelector('#product-image');im.src=`assets/xpeng/image${b.dataset.product}.webp`;im.alt=`原始产品渲染：${b.textContent}`;document.querySelector('#product-caption').textContent=b.dataset.caption;im.animate([{opacity:.25},{opacity:1}],{duration:reduced?0:450});}));
